def evaluate(store, task, profile, compute):
    # Check owner mismatch
    if task['owner'] != profile['owner']:
        raise PermissionError('Owner mismatch')

    # Check version mismatch
    if task['version'] != profile['version']:
        return None

    # Create cache key
    key = (task['owner'], profile['version'], task['criteria_version'], task['job_text'])

    # Check if result is in cache
    if key in store:
        return store[key]

    # Compute result and cache it
    try:
        result = compute()
        store[key] = result
    except Exception as e:
        raise e

    return result

import service

# Mock compute function
def mock_compute():
    return 'result'

# Mock store
store = {}

# Mock task and profile
valid_task = {'owner': 'user1', 'version': '1.0', 'job_text': 'job1', 'criteria_version': '1.0'}
valid_profile = {'owner': 'user1', 'version': '1.0'}

# Test owner mismatch
try:
    service.evaluate(store, {'owner': 'user2', 'version': '1.0', 'job_text': 'job1', 'criteria_version': '1.0'}, valid_profile, mock_compute)
except PermissionError:
    pass
else:
    assert False, 'Expected PermissionError for owner mismatch'

# Test version mismatch
assert service.evaluate(store, {'owner': 'user1', 'version': '2.0', 'job_text': 'job1', 'criteria_version': '1.0'}, valid_profile, mock_compute) is None, 'Expected None for version mismatch'

# Test caching
assert service.evaluate(store, valid_task, valid_profile, mock_compute) == 'result', 'Expected cached result'
assert service.evaluate(store, valid_task, valid_profile, mock_compute) == 'result', 'Expected cached result'

# Test exception propagation
def failing_compute():
    raise ValueError('Test exception')
try:
    service.evaluate(store, valid_task, valid_profile, failing_compute)
except ValueError as e:
    assert str(e) == 'Test exception', 'Expected exception propagation'
else:
    assert False, 'Expected exception propagation'

print('All tests passed')

